-- 📚 꼭집 주거 사전 — 영구임대 가군·나군 · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값.
-- 확인 2026-10-13 · 실행 3.1초 · 결과:
-- {"anns": 29, "by_std": {"영구임대": 29}, "가군나군": 2, "가군나군_ex": ["2015122300020680", "2015122300020233"], "가군수급자": 13, "가군수급자_ex": ["2015122300020874", "2015122300020868", "2015122300020866"]}
with a as(select distinct on(x.announcement_id)x.announcement_id,x.supply_org org,coalesce(m.std_type,x.housing_type)std,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x left join housing_type_map m on m.source_table='announcements' and m.source=x.source and m.housing_type=x.housing_type order by x.announcement_id,(x.source='LH')desc,x.created_at desc),y as(select p.announcement_id,regexp_replace(p.content_raw,'\s+',' ','g')t,coalesce(r.class_name,c.class_name)cls,a.org,a.std from announcement_policies p join a using(announcement_id) left join policy_row_classes r on r.policy_id=p.id and r.axis='standard' left join policy_category_classes c on c.category=p.category and c.axis='standard' where a.yr=2026)select json_build_object('anns',(select count(distinct announcement_id) from y where std='영구임대'),'by_std',(select json_object_agg(std,n) from(select std,count(distinct announcement_id)n from y where std='영구임대' group by 1)q),'가군나군',(select count(distinct announcement_id) from y where std='영구임대' and t~'가\s*군[^.]{0,80}나\s*군'),'가군나군_ex',(select json_agg(i) from(select distinct announcement_id i from y where std='영구임대' and t~'가\s*군[^.]{0,80}나\s*군' order by 1 desc limit 3)q),'가군수급자',(select count(distinct announcement_id) from y where std='영구임대' and t~'가\s*군[^.]{0,60}(수급자|차상위)'),'가군수급자_ex',(select json_agg(i) from(select distinct announcement_id i from y where std='영구임대' and t~'가\s*군[^.]{0,60}(수급자|차상위)' order by 1 desc limit 3)q))j;
